#!/usr/bin/env node

// Bundle the in-repo SDK docs into packages/sdk/docs/ so the published tarball
// carries them — replacing the old unpinned remote download in postinstall.
// Idempotent: removes the target first so prepack + an explicit CI step never
// leave stale files behind.

import { execFileSync } from 'child_process';
import { existsSync, rmSync, cpSync } from 'fs';
import { resolve as resolvePath, dirname, basename } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const SDK_DIR = resolvePath(__dirname, '..');
const DOCS_SRC = resolvePath(SDK_DIR, '..', 'sdk-docs');
const DOCS_DEST = resolvePath(SDK_DIR, 'docs');

// Mirror cd-sdk-docs.yml's exclusions, plus the docs-package plumbing that has
// no place in the consumer tarball.
const EXCLUDE = new Set([
  '.git',
  '.github',
  '.gitbook',
  'node_modules',
  'scripts',
  'package.json',
  'package-lock.json',
]);

function main() {
  if (!existsSync(DOCS_SRC)) {
    console.error(`copy-docs: docs source not found at ${DOCS_SRC}`);
    process.exit(1);
  }

  // Regenerate agents-index.txt in the source first (matches cd-sdk-docs.yml)
  // so the bundled index never ships stale.
  // Keep stdout clean: this runs as prepack, and `npm pack --json` consumers
  // parse stdout, so all logging must go to stderr.
  execFileSync('npx', ['-y', 'tsx', 'scripts/generate-agents-index.ts'], {
    cwd: DOCS_SRC,
    stdio: ['ignore', 2, 'inherit'],
  });

  rmSync(DOCS_DEST, { recursive: true, force: true });
  cpSync(DOCS_SRC, DOCS_DEST, {
    recursive: true,
    filter: (src) => !EXCLUDE.has(basename(src)),
  });

  console.error(`copy-docs: bundled docs into ${DOCS_DEST}`);
}

main();
